    private static final Map<Character, String> MAP = new HashMap<>();

    static {
        // 格式：字 + 音节(带声调数字)，条目之间用 ';' 分隔
        int start = 0;
        while (start < DATA.length()) {
            int end = DATA.indexOf(';', start);
            if (end < 0) {
                end = DATA.length();
            }
            if (end > start + 1) {
                char key = DATA.charAt(start);
                String value = DATA.substring(start + 1, end);
                if (!MAP.containsKey(key)) {
                    MAP.put(key, value);
                }
            }
            start = end + 1;
        }
    }

    private PinyinTable() {
    }

    /** 取单个汉字的完整拼音（带声调数字）；没有收录返回 null。 */
    public static String pinyinOf(char c) {
        return MAP.get(c);
    }

    /**
     * 把一段汉字转成拼音串（空格分隔，带声调数字）；未收录的字原样保留。
     *
     * <p>用于排序键：{@code "雪降" → "xue3 jiang4"}。</p>
     */
    public static String pinyinOf(String text) {
        if (text == null || text.isEmpty()) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            String py = pinyinOf(c);
            if (py == null) {
                sb.append(c);
            } else {
                if (sb.length() > 0) {
                    sb.append(' ');
                }
                sb.append(py);
            }
        }
        return sb.toString();
    }
